exercises.solution:
const funkcjaLogujaca = null;
funkcjaLogujaca?.("test"); // brak bledu, nic sie nie dzieje
console.log("kod wykonal sie dalej bez bledu");

const elementy = [{ nazwa: "A", dane: { ilosc: 5 } }, { nazwa: "B" }];
elementy.forEach(el => {
  console.log(el.nazwa, el.dane?.ilosc ?? "brak");
});
// A 5
// B brak

const liczbaPunktow = 0;
console.log(liczbaPunktow || 100); // 100 - || traktuje 0 jako 'brak wartosci'
console.log(liczbaPunktow ?? 100); // 0 - ?? poprawnie zachowuje 0 jako realna wartosc
// roznica: || reaguje na WSZYSTKIE falsy (w tym 0), ?? WYLACZNIE na null/undefined

function pokazWynikZle(punkty) {
  return punkty || 100;
}

console.log(pokazWynikZle(0)); // 100 - BLEDNIE, 0 to PRAWDZIWY wynik

function pokazWynik(punkty) {
  return punkty ?? 100;
}

console.log(pokazWynik(0));         // 0 - POPRAWNIE
console.log(pokazWynik(undefined)); // 100 - fallback zadzialal, gdy TRZEBA

function wywolajCallback(callback, dane) {
  callback?.(dane);
}

wywolajCallback(d => console.log(`Otrzymano: ${d}`), "test"); // Otrzymano: test
wywolajCallback(undefined, "test"); // nic sie nie dzieje, bez bledu

function pobierzLimit(limit) {
  return limit ?? 10;
}

console.log(pobierzLimit(0));         // 0 - POPRAWNIE zachowane
console.log(pobierzLimit(undefined)); // 10 - fallback

const formularz = { pole: "" };
console.log(formularz.pole || "wartosc domyslna"); // "wartosc domyslna" - BLEDNIE nadpisuje pusty string
console.log(formularz.pole ?? "wartosc domyslna"); // "" - POPRAWNIE zachowuje pusty string

function pobierzUstawienie(ustawienia, klucz, domyslna) {
  return ustawienia?.[klucz] ?? domyslna;
}

console.log(pobierzUstawienie(null, "rozmiar", 10));               // 10
console.log(pobierzUstawienie({ rozmiar: 12 }, "rozmiar", 10));    // 12

const uzytkownik = { imie: "Jan", walidujDane: null };
uzytkownik.walidujDane?.();
console.log("kod kontynuuje dzialanie bez bledu");

const zamowienia = [{ id: 1, klient: { imie: "Jan" } }, { id: 2, klient: null }];
const imiona = zamowienia.map(z => z.klient?.imie ?? "Anonim");
console.log(imiona); // ['Jan', 'Anonim']

const wartoscA = null;
const wartoscB = undefined;
console.log(wartoscA ?? wartoscB ?? "ostateczny fallback"); // "ostateczny fallback"

const produkt = { nazwa: "Kubek", cena: 0 };
function sformatujCene(cena) {
  return `${cena ?? "N/A"} zl`;
}

console.log(sformatujCene(produkt.cena)); // "0 zl" - POPRAWNIE, nie "N/A"

function bezpiecznaSuma(a, b) {
  return (a ?? 0) + (b ?? 0);
}

console.log(bezpiecznaSuma(5));           // 5
console.log(bezpiecznaSuma(undefined, 10)); // 10

const komentarze = [
  { tresc: "Super!", autor: { imie: "Ala" } },
  { tresc: "OK", autor: null }
];

const sformatowane = komentarze.map(k => `${k.tresc} - ${k.autor?.imie ?? "Anonim"}`);
console.log(sformatowane); // ['Super! - Ala', 'OK - Anonim']

const wynikZapytania = false;
console.log(wynikZapytania || "domyslny"); // "domyslny" - BLEDNIE nadpisuje poprawne false
console.log(wynikZapytania ?? "domyslny"); // false - POPRAWNIE zachowuje wartosc

function pobierzGleboka(obiekt) {
  return obiekt?.a?.b?.c?.d ?? "brak danych";
}

console.log(pobierzGleboka({}));                                    // "brak danych"
console.log(pobierzGleboka({ a: { b: { c: { d: "znaleziono" } } } })); // "znaleziono"

